func (t ReviewFlag) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "code_conflict":
		return t.AsCodeConflictFlag()
	case "line_math":
		return t.AsLineMathFlag()
	case "low_confidence":
		return t.AsLowConfidenceFlag()
	case "missing_field":
		return t.AsMissingFieldFlag()
	case "possible_duplicate":
		return t.AsPossibleDuplicateFlag()
	case "sum_mismatch":
		return t.AsSumMismatchFlag()
	case "uncertain_match":
		return t.AsUncertainMatchFlag()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

